	}
	fullPath := filepath.Join(brainDir, snapshotPath)
	symbolsByID, err := loadSemanticSymbolsByIDSnapshot(fullPath)
	if err != nil {
		return nil, nil, err
	}
	relations, err := findSemanticRelationsByTypesSnapshot(fullPath, relationTypes)
